import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def E(source, locator, note):
    return {"source": source, "locator": locator, "note": note}


def Q(missing=(), warnings=(), status="partial"):
    return {"status": status, "extraction_confidence": "medium", "completed_sections": ["article", "catalog", "construction_workflow", "additional_information"], "missing_core_fields": list(missing), "warnings": list(warnings), "needs_human_review": status != "verified"}


def out(case, sid, d):
    p = ROOT / f"data/{case}/references/{sid}/parsed/extraction/{sid}__extraction.json"
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(d, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


